import{_ as d,o as a,c as r,ag as e}from"./chunks/framework.KxDd3USm.js";const b=JSON.parse('{"title":"12.5 压缩与容量题统一模板 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"12-数学与多媒体/05-压缩与容量题模板.md","filePath":"12-数学与多媒体/05-压缩与容量题模板.md"}'),l={name:"12-数学与多媒体/05-压缩与容量题模板.md"};function o(i,t,h,n,s,p){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="_12-5-压缩与容量题统一模板-★★★" tabindex="-1">12.5 压缩与容量题统一模板 ★★★ <a class="header-anchor" href="#_12-5-压缩与容量题统一模板-★★★" aria-label="Permalink to &quot;12.5 压缩与容量题统一模板 ★★★&quot;">​</a></h1><h3 id="_10-1-为什么能压缩" tabindex="-1">10.1 为什么能压缩 <a class="header-anchor" href="#_10-1-为什么能压缩" aria-label="Permalink to &quot;10.1 为什么能压缩&quot;">​</a></h3><p>多媒体中存在多种冗余：</p><ul><li>空间冗余：相邻像素常相似；</li><li>时间冗余：相邻视频帧常只有局部变化；</li><li>统计冗余：有些符号出现频率远高于另一些；</li><li>感知冗余：人眼、人耳对某些细节不敏感。</li></ul><p>压缩比常写：</p><p><strong>压缩比 = 压缩前容量 / 压缩后容量</strong></p><p>例：100 MiB 压成 5 MiB，压缩比为 <code>100/5=20:1</code>。若说“压缩后是原来的 5%”，则压缩后容量=<code>100×5%=5 MiB</code>。</p><p><strong>反例</strong>：“压缩率 20%”在不同资料中可能指压缩后占 20%，也可能指减少了 20%。题面含糊时优先看它给出的定义；讲义和严谨题目应直接说“压缩比”或“压缩后占原大小百分比”。</p><h3 id="_10-2-无损与有损" tabindex="-1">10.2 无损与有损 <a class="header-anchor" href="#_10-2-无损与有损" aria-label="Permalink to &quot;10.2 无损与有损&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>解压后</th><th>适用</th><th>常见方法/格式</th></tr></thead><tbody><tr><td>无损压缩</td><td>与原数据完全一致</td><td>程序、文本、图标、需精确还原的数据</td><td>RLE、Huffman、LZW、PNG、GIF、ZIP</td></tr><tr><td>有损压缩</td><td>允许丢失部分信息</td><td>照片、音频、视频</td><td>JPEG、MP3、常见 MPEG 编码</td></tr></tbody></table><p>有损不等于“文件损坏”，而是有控制地舍弃人类不敏感的信息，用质量换更高压缩比。</p><h3 id="_10-3-常见图像格式" tabindex="-1">10.3 常见图像格式 <a class="header-anchor" href="#_10-3-常见图像格式" aria-label="Permalink to &quot;10.3 常见图像格式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>格式</th><th>典型特点</th><th>易错点</th></tr></thead><tbody><tr><td>BMP</td><td>常见为未压缩或简单压缩位图</td><td>容量通常较大</td></tr><tr><td>GIF</td><td>无损、最多 256 色、支持简单动画和透明</td><td>不适合真彩照片</td></tr><tr><td>PNG</td><td>无损、支持 Alpha 透明</td><td>适合界面、截图、图标</td></tr><tr><td>JPEG/JPG</td><td>有损、适合连续色调照片</td><td>不适合反复编辑保存、文字锐利边缘</td></tr></tbody></table><h3 id="_10-4-jpeg-的核心过程" tabindex="-1">10.4 JPEG 的核心过程 <a class="header-anchor" href="#_10-4-jpeg-的核心过程" aria-label="Permalink to &quot;10.4 JPEG 的核心过程&quot;">​</a></h3><p>典型 JPEG 思路：颜色变换与色度抽样 → 分块 → <strong>DCT（离散余弦变换）</strong> → <strong>量化</strong> → 熵编码。</p><ul><li>DCT 把空间像素转换为频率系数，本身可逆；</li><li><strong>量化</strong>会丢弃/粗化部分系数，是主要有损环节；</li><li>熵编码利用统计冗余，属于无损编码步骤。</li></ul><p><strong>反例</strong>：不能笼统说“JPEG 每一步都有损”。导致信息不可精确恢复的核心通常是量化和可能的色度抽样，Huffman 等熵编码本身可逆。</p><h3 id="_10-5-mpeg-与帧间压缩" tabindex="-1">10.5 MPEG 与帧间压缩 <a class="header-anchor" href="#_10-5-mpeg-与帧间压缩" aria-label="Permalink to &quot;10.5 MPEG 与帧间压缩&quot;">​</a></h3><p>MPEG 面向运动图像及相关音频，既利用单帧内的<strong>空间冗余</strong>，也利用帧与帧之间的<strong>时间冗余</strong>。</p><table tabindex="0"><thead><tr><th>帧类型</th><th>含义</th><th>依赖关系</th></tr></thead><tbody><tr><td>I 帧</td><td>帧内编码图像，可独立解码</td><td>不依赖其他帧</td></tr><tr><td>P 帧</td><td>前向预测编码</td><td>依赖前面的 I/P 帧</td></tr><tr><td>B 帧</td><td>双向预测编码</td><td>参考前后帧，压缩潜力高</td></tr></tbody></table><p>常见标准印象：JPEG 主要针对静止图像；MPEG 系列主要针对运动图像/音视频；MP3 是有损音频压缩。</p><p><strong>应试动作</strong>：要求完全恢复选无损；照片优先 JPEG；透明界面图优先 PNG；简单动画常见 GIF；视频想到 MPEG 与时间冗余。问 JPEG 哪一步主要有损，选量化。</p><hr><h2 id="第十一节-容量题统一解题模板-★★★" tabindex="-1">第十一节 容量题统一解题模板 ★★★ <a class="header-anchor" href="#第十一节-容量题统一解题模板-★★★" aria-label="Permalink to &quot;第十一节 容量题统一解题模板 ★★★&quot;">​</a></h2><p>考试时在草稿纸固定写四行：</p><ol><li>写原始公式，列出所有维度；</li><li>把 kHz、分钟等统一为 Hz、秒；</li><li>先算 bit，除以 8 得 Byte；</li><li>若有压缩，再用原容量除以压缩比，并做数量级检查。</li></ol><p>三条公式并排背：</p><table tabindex="0"><thead><tr><th>媒体</th><th>未压缩容量（Byte）</th></tr></thead><tbody><tr><td>图像</td><td>宽×高×位深÷8</td></tr><tr><td>音频</td><td>采样率×量化位数×声道×秒÷8</td></tr><tr><td>视频</td><td>宽×高×位深×帧率×秒÷8</td></tr></tbody></table><p>数量级检查：</p><ul><li>24 bit 图像每像素 3 B；</li><li>CD 级双声道音频每秒约 <code>44100×2×2≈176 KB</code>；</li><li>未压缩高清视频每秒往往几十到上百 MB，所以算出“10 秒只有几 KB”一定漏乘了某项。</li></ul><hr>',31)])])}const P=d(l,[["render",o]]);export{b as __pageData,P as default};
